lex;justify-content:space-between;font-size:.64rem}.breakdown-top span{color:#7689a1}.bar{height:6px;background:#1d2c40;border-radius:99px;margin-top:9px;overflow:hidden}.bar i{display:block;height:100%;border-radius:99px}.formula{padding:13px;background:#101d2e;border:1px solid #263a52;border-radius:11px;color:#8497af;font-size:.67rem;line-height:1.55;margin-top:12px}.mini-chart{height:235px}.notice{color:#ffd05b;font-size:.67rem;margin-bottom:10px}@media(max-width:950px){.risk-overview,.risk-grid{grid-template-columns:1fr}.risk-select{min-width:0;width:100%}.risk-head{align-items:flex-start;flex-direction:column}}</style>
<div class="risk-page"><header class="risk-head"><div><div class="kicker">RISK ANALYTICS STUDIO</div><h1>Country Risk Intelligence</h1><p>Analisis tren dan komposisi weighted risk dari seluruh snapshot.</p></div><select class="risk-select" id="country">@foreach($countries as $country)<option value="{{ $country->code_iso2 }}" data-name="{{ $country->name }}" data-region="{{ $country->region }}" @selected($country->code_iso2==='ID')>{{ $country->name }} · {{ $country->riskScores->isNotEmpty()?'data tersedia':'belum tersedia' }}</option>@endforeach</select></header><div class="notice" id="notice"></div><section class="risk-overview"><article class="score-card"><img id="riskFlag" alt=""><h2 id="riskCountry">—</h2><p id="riskRegion">—</p><div class="score-ring" id="scoreRing"><div><strong id="scoreValue">0</strong><span>RISK SCORE</span></div></div><span class="score-status" id="scoreStatus">Belum dinilai</span></article><article class="trend-card"><div class="panel-head"><h2>Composite Risk Timeline</h2><span>Historical snapshots</span></div><div class="chart-main"><canvas id="riskTrend"></canvas></div></article></section><section class="risk-grid"><article class="risk-panel"><div class="panel-head"><h2>Risk Composition</h2><span>Weighted inputs</span></div><div class="breakdown-grid" id="breakdown"></div><div class="formula">Formula: Weather 30% + Inflation 20% + News Sentiment 40% + Currency 10%. Skor merupakan decision-support indicator, bukan prediksi absolut.</div></article><article class="risk-panel"><div class="panel-head"><h2>Economic Context</h2><span>GDP & inflation history</span></div><div class="mini-chart"><canvas id="economicContext"></canvas></div></article></section></div>
<script>let riskChart,economicChart;const colors={weather:'#37c8ff',inflation:'#fbbf24',news:'#ff7189',currency:'#9878ff'};async function loadRisk(){const select=document.getElementById('country'),code=select.value,option=select.options[select.selectedIndex];notice.textContent='Memuat intelligence snapshot...';riskCountry.textContent=option.dataset.name;riskRegion.textContent=option.dataset.region||'—';riskFlag.src=`https://flagcdn.com/w160/${code.toLowerCase()}.png`;try{const [r,e]=await Promise.all([fetch(`/api/countries/${code}/risk-trend`).then(x=>x.json()),fetch(`/api/countries/${code}/economy`).then(x=>x.json())]),risks=r.data||[],economy=e.data||[],last=risks.at(-1);notice.textContent=last?'':`Belum ada snapshot ${code}. Gunakan tombol Sync pada Report Center.`;const score=Number(last?.total_score||0),color=score>=70?'#ff7189':score>=40?'#fbbf24':'#35e6b1';scoreValue.textContent=Math.round(score);scoreStatus.textContent=last?.status||'Belum dinilai';scoreRing.style.setProperty('--score',score);scoreRing.style.setProperty('--risk-color',color);scoreStatus.style.setProperty('--risk-color',color);const parts=[['Weather',last?.weather_risk||0,'weather'],['Inflation',last?.inflation_risk||0,'inflation'],['News sentiment',last?.news_risk||0,'news'],['Currency',last?.currency_risk||0,'currency']];breakdown.innerHTML=parts.map(p=>`<div class="breakdown"><div class="breakdown-top"><span>${p[0]}</span><strong>${p[1]}</strong></div><div class="bar"><i style="width:${Math.min(p[1],100)}%;background:${colors[p[2]]}"></i></div></div>`).join('');riskChart?.destroy();riskChart=new Chart(riskTrend,{type:'line',data:{labels:risks.map(x=>x.created_at.slice(0,10)),datasets:[{label:'Risk score',data:risks.map(x=>x.total_score),borderColor:color,backgroundColor:color+'25',fill:true,tension:.35,pointRadius:3}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{x:{grid:{display:false},ticks:{color:'#72849d'}},y:{min:0,max:100,grid:{color:'rgba(130,150,175,.09)'},ticks:{color:'#72849d'}}}}});economicChart?.destroy();economicChart=new Chart(economicContext,{type:'line',data:{labels:economy.map(x=>x.year),datasets:[{label:'Inflation %',data:economy.map(x=>x.inflation),borderColor:'#fbbf24',tension:.35},{label:'GDP growth index',data:economy.map((x,i,a)=>a[0]?.gdp?x.gdp/a[0].gdp*100:null),borderColor:'#35e6b1',tension:.35}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{labels:{color:'#92a4ba',usePointStyle:true}}},scales:{x:{grid:{display:false},ticks:{color:'#72849d'}},y:{grid:{color:'rgba(130,150,175,.09)'},ticks:{color:'#72849d'}}}}})}catch(e){notice.textContent='Data gagal dimuat. Coba refresh halaman.'}}country.addEventListener('change',loadRisk);loadRisk();</script>
